var e={rules:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Automatiza tu impresora con reglas seguras de tipo SI-ENTONCES. Desactivadas por defecto; activa cada regla tú mismo.`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`Aún no hay reglas. Añade una abajo y actívala cuando estés listo.`}},engine:{on:{t:0,b:{t:2,i:[{t:3}],s:`El motor de reglas está ACTIVO`}},off:{t:0,b:{t:2,i:[{t:3}],s:`El motor de reglas está INACTIVO`}},turnOn:{t:0,b:{t:2,i:[{t:3}],s:`Activar`}},turnOff:{t:0,b:{t:2,i:[{t:3}],s:`Desactivar`}},masterNote:{t:0,b:{t:2,i:[{t:3}],s:`Nada se ejecuta hasta que el motor y la regla individual estén activos.`}}},triggers:{print_complete:{t:0,b:{t:2,i:[{t:3}],s:`Cuando termina una impresión`}},print_error:{t:0,b:{t:2,i:[{t:3}],s:`Cuando la impresora da un error`}},temp_above:{t:0,b:{t:2,i:[{t:3}],s:`Cuando un calentador supera`}},temp_below:{t:0,b:{t:2,i:[{t:3}],s:`Cuando un calentador baja de`}}},actions:{notify:{t:0,b:{t:2,i:[{t:3}],s:`Registrar una notificación`}},gcode:{t:0,b:{t:2,i:[{t:3}],s:`Ejecutar un comando g-code`}}},rule:{armed:{t:0,b:{t:2,i:[{t:3}],s:`Activada`}},arm:{t:0,b:{t:2,i:[{t:3}],s:`Desactivada`}},edit:{t:0,b:{t:2,i:[{t:3}],s:`Editar`}},delete:{t:0,b:{t:2,i:[{t:3}],s:`Eliminar`}},confirmDelete:{t:0,b:{t:2,i:[{t:3}],s:`Eliminar regla`}}},form:{name:{t:0,b:{t:2,i:[{t:3}],s:`Nombre de la regla`}},namePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`p. ej. Apagar calentadores tras imprimir`}},trigger:{t:0,b:{t:2,i:[{t:3}],s:`Si (activador)`}},action:{t:0,b:{t:2,i:[{t:3}],s:`Entonces (acción)`}},heater:{t:0,b:{t:2,i:[{t:3}],s:`Calentador`}},value:{t:0,b:{t:2,i:[{t:3}],s:`Temperatura (°C)`}},message:{t:0,b:{t:2,i:[{t:3}],s:`Mensaje`}},messagePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`Mostrado en el registro de reglas`}},gcode:{t:0,b:{t:2,i:[{t:3}],s:`G-code`}},gcodePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`p. ej. TURN_OFF_HEATERS`}},save:{t:0,b:{t:2,i:[{t:3}],s:`Guardar regla`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Cancelar`}},add:{t:0,b:{t:2,i:[{t:3}],s:`Añadir una regla`}}},log:{title:{t:0,b:{t:2,i:[{t:3}],s:`Actividad reciente`}},outcome:{notify:{t:0,b:{t:2,i:[{t:3}],s:`notificado`}},ran:{t:0,b:{t:2,i:[{t:3}],s:`ejecutó g-code`}},skipped_busy:{t:0,b:{t:2,i:[{t:3}],s:`omitido (impresora ocupada)`}},error:{t:0,b:{t:2,i:[{t:3}],s:`error`}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Guía`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Guía del motor de reglas`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Cerrar`}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:`¿Qué es el motor de reglas?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Vigila la impresora y ejecuta una acción cuando se cumple una condición que defines; por ejemplo, registrar una nota cuando termina una impresión o apagar los calentadores. Cada regla es SI (un activador) ENTONCES (una acción).`}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:`Cómo se mantiene seguro`}},body:{t:0,b:{t:2,i:[{t:3}],s:`El motor está desactivado por defecto y cada regla debe activarse individualmente, así nada se ejecuta por sorpresa. Una regla se dispara una vez cuando su condición se cumple por primera vez. Las acciones de g-code solo se ejecutan cuando la impresora está inactiva (se rechazan durante una impresión) y cada resultado se registra.`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Glosario`}}}},glossary:{trigger:{term:{t:0,b:{t:2,i:[{t:3}],s:`Activador`}},def:{t:0,b:{t:2,i:[{t:3}],s:`La condición que inicia una regla, p. ej. que termine una impresión o que un calentador cruce una temperatura.`}}},action:{term:{t:0,b:{t:2,i:[{t:3}],s:`Acción`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Lo que hace la regla cuando se dispara: registrar una notificación o ejecutar un comando g-code (solo cuando está inactiva).`}}},armed:{term:{t:0,b:{t:2,i:[{t:3}],s:`Activada`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Una regla que está encendida. Las reglas desactivadas se conservan pero nunca se disparan.`}}}}}}};export{e as default};